import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const L=JSON.parse('{"title":"术语表","description":"","frontmatter":{"title":"术语表"},"headers":[],"relativePath":"sql-orm-course/glossary.md","filePath":"sql-orm-course/docs/glossary.md"}'),o={name:"sql-orm-course/glossary.md"};function i(n,t,s,c,l,S){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>全书首教过的名词，按课程出场顺序的归类整理；每条一句话定义，出处见各章首现位置。</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话定义</th></tr></thead><tbody><tr><td>数据库</td><td>database</td><td>一个专门负责存数据和查数据的独立程序，你用 SQL 跟它对话，它把结果按行还给你。</td></tr><tr><td>表</td><td>table</td><td>数据库里的一张二维表：列定形状和类型，一行就是一条记录，像一张带表头的 Excel。</td></tr><tr><td>行</td><td>row</td><td>表里的一条记录，对应前端世界里的一个对象。</td></tr><tr><td>列</td><td>column</td><td>表的一竖条，规定名字和类型，对应对象的一个字段——但类型是全表统一的。</td></tr><tr><td>SQL</td><td>Structured Query Language</td><td>跟数据库说话的固定句式语言，读数据写 SELECT、写数据用 INSERT/UPDATE/DELETE、描述表结构用 CREATE TABLE。</td></tr><tr><td>声明式</td><td>declarative</td><td>只说要什么、不说怎么做的写法，像 CSS 选择器；SQL 是声明式的：写条件，遍历交给数据库。</td></tr><tr><td>主键</td><td>primary key</td><td>一行数据的身份证号：全表唯一，靠它精确定位某一行；「永不复用」是本分，SQLite 里要显式加 AUTOINCREMENT 才兑现。</td></tr><tr><td>外键</td><td>foreign key</td><td>一列里存的是另一张表某行的主键，相当于数据库帮你验证过的「指向另一行的指针」。</td></tr><tr><td>约束</td><td>constraint</td><td>写在表定义里的守门规则（非空、唯一等），非法数据在写入那一刻就被数据库拦下。</td></tr><tr><td>聚合函数</td><td>aggregate function</td><td>把多行压成一个数的内置动作，如 COUNT 数行数、SUM 求和、AVG 求平均。</td></tr><tr><td>分组</td><td>GROUP BY</td><td>按某列的值把行分桶，每个桶各自出聚合结果，像先 Map 分组再各自 reduce。</td></tr><tr><td>连接</td><td>JOIN</td><td>按两表的关联列把行配成对的 SQL 写法，把前端手写的「两数组按 id 匹配」搬进数据库。</td></tr><tr><td>索引</td><td>index</td><td>为某列额外建的一份排好序的目录，让按这列查不用从头翻到尾。</td></tr><tr><td>B-tree</td><td>B-tree</td><td>索引常用的有序树结构：从中间分叉、逐层缩小范围，几步就定位目标，像按拼音排好的通讯录。</td></tr><tr><td>查询计划</td><td>query plan</td><td>数据库自述的执行方案；EXPLAIN 命令让它交代打算全表扫还是走索引。</td></tr><tr><td>全表扫描</td><td>full table scan</td><td>没有可用索引时数据库只能从第一行翻到最后一行的执行方式，行数涨多少它就慢多少。</td></tr><tr><td>ORM</td><td>object-relational mapping</td><td>对象关系映射：一层翻译器，这边写对象与链式调用，那边生成并执行 SQL，行与对象互相自动转换。</td></tr><tr><td>Active Record</td><td>Active Record</td><td>ORM 一派：数据对象自带增删改能力，user.save() 直接写库。</td></tr><tr><td>Data Mapper</td><td>Data Mapper</td><td>ORM 另一派：数据只是纯数据，读写交给独立的映射器对象，两者分开。</td></tr><tr><td>SQL 注入</td><td>SQL injection</td><td>拼接字符串时用户输入被当成了 SQL 代码执行，数据库世界的 XSS。</td></tr><tr><td>参数化查询</td><td>parameterized query</td><td>SQL 模板里放 ? 占位符、数据单独传的写法，用户输入永远只是数据、成不了代码。</td></tr><tr><td>预编译语句</td><td>prepared statement</td><td>先把 SQL 模板交给数据库解析好、再反复填参数执行的机制，参数化查询的底层实现。</td></tr><tr><td>数据定义语言</td><td>DDL, data definition language</td><td>描述数据结构的那类 SQL（CREATE/ALTER/DROP），盖楼的图纸；与之相对的 DML 是搬家具（增删改查）。</td></tr><tr><td>查询构建器</td><td>query builder</td><td>用链式调用攒条件、最后一步编译成 SQL 的库， knex 是典型；ORM 的查询半身。</td></tr><tr><td>水合</td><td>hydration</td><td>把查回来的裸行变成带方法的类实例的过程——注意与 SSR 的同名概念无关。</td></tr><tr><td>脏跟踪</td><td>dirty tracking</td><td>实例自己记着哪些字段被改过，save 时只把这些字段的列写回数据库。</td></tr><tr><td>N+1 问题</td><td>N+1 query problem</td><td>查 1 次列表再逐行查关联、共发出 N+1 条 SQL 的病症，靠批量加载治愈。</td></tr><tr><td>事务</td><td>transaction</td><td>把多条 SQL 捆成一个整体：全部成功才提交，任何一步失败就整体回滚，像可撤销的 git commit。</td></tr><tr><td>原子性</td><td>atomicity</td><td>事务的核心承诺：里面的一串操作要么全发生、要么全没发生，不存在做一半。</td></tr><tr><td>迁移</td><td>migration</td><td>把表结构的每次变更写成带序号的脚本，像表结构的 git 历史，可回放可回滚。</td></tr><tr><td>连接池</td><td>connection pool</td><td>预建好一组数据库连接排队复用的机制，免得每个请求都付一次建连接的成本。</td></tr><tr><td>方言</td><td>dialect</td><td>各家数据库 SQL 的细微差异，如分页写法 MySQL 与 SQLite 就不同。</td></tr></tbody></table>',3)])])}const u=d(o,[["render",i]]);export{L as __pageData,u as default};
